import base64,json,pathlib,tempfile,subprocess,sys,shlex
files={'make_sample.py': '"""Create three small fictional labeled PDFs only in a NEW sample folder.\n\nEvery existing sample path is refused. Files are created exclusively.\nAn interrupted setup can leave a partial new folder; do not delete old\nwork to force a retry. Start in a different new empty lesson folder.\n"""\nfrom pathlib import Path\nimport stat\nfrom pypdf import PdfWriter\nfrom pypdf.generic import DictionaryObject, NameObject, DecodedStreamObject\n\n\ndef safe_input(value, directory=False):\n    path = Path(value).absolute()\n    if \'..\' in path.parts:\n        raise OSError(\'Parent-traversal paths are unsupported.\')\n    for part in [*reversed(path.parents), path]:\n        info = part.lstat()\n        if stat.S_ISLNK(info.st_mode) or getattr(info, \'st_file_attributes\', 0) & 0x400:\n            raise OSError(\'Links/reparse points are unsupported.\')\n    info = path.lstat()\n    if directory:\n        if not stat.S_ISDIR(info.st_mode):\n            raise NotADirectoryError(\'Expected an ordinary directory.\')\n    elif not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:\n        raise OSError(\'Expected an ordinary singly linked file.\')\n    return path\n\ndef safe_output(value):\n    path = Path(value).absolute()\n    if \'..\' in path.parts:\n        raise OSError(\'Parent-traversal paths are unsupported.\')\n    safe_input(path.parent, directory=True)\n    return Path(value)\n\n\ndef make(path, labels, size):\n    safe_output(path)\n    writer = PdfWriter()\n    font = DictionaryObject({NameObject(\'/Type\'): NameObject(\'/Font\'),\n        NameObject(\'/Subtype\'): NameObject(\'/Type1\'), NameObject(\'/BaseFont\'): NameObject(\'/Helvetica\')})\n    for label in labels:\n        page = writer.add_blank_page(width=size[0], height=size[1])\n        page[NameObject(\'/Resources\')] = DictionaryObject({NameObject(\'/Font\'):\n            DictionaryObject({NameObject(\'/F1\'): writer._add_object(font)})})\n        content = DecodedStreamObject()\n        content.set_data((\'BT /F1 22 Tf 60 650 Td (%s) Tj ET\' % label).encode(\'ascii\'))\n        page[NameObject(\'/Contents\')] = writer._add_object(content)\n    with Path(path).open(\'xb\') as handle:\n        writer.write(handle)\n\n\ndef setup(root):\n    root = safe_output(root)\n    root.mkdir()\n    make(root / \'contract.pdf\', [\'FICTIONAL CONTRACT - PAGE 1\', \'FICTIONAL CONTRACT - PAGE 2\'], (612, 792))\n    make(root / \'invoice.pdf\', [\'FICTIONAL INVOICE - PAGE 1\', \'FICTIONAL INVOICE - PAGE 2\', \'FICTIONAL INVOICE - PAGE 3\'], (595, 842))\n    make(root / \'notes.pdf\', [\'FICTIONAL NOTES - PAGE 1\'], (612, 792))\n\n\nif __name__ == \'__main__\':\n    try:\n        setup(Path(__file__).absolute().parent / \'sample\')\n    except FileExistsError:\n        raise SystemExit(\'Stopped: sample already exists. Nothing was replaced or deleted.\')\n    print(\'Created three fictional labeled PDFs in a new sample folder (2, 3 and 1 pages).\')\n', 'pdfkit.py': '"""Small PDF page tool. Use only trusted, backed-up, ordinary PDFs.\n\ncount FILE... | merge OUT IN... | split IN OUT FIRST-LAST |\nrotate IN OUT DEGREES [--page N]\n\nOutputs are created exclusively: every existing destination is refused,\nincluding an input path or a link. Inputs must be ordinary singly linked files with ordinary ancestors.\nLinks/reparse points, special files and traversal refuse before reading. This copies pages, not the whole PDF document: signatures,\nforms, outlines, metadata and other document features are not promised.\nCounts alone do not prove content or order. Inspect the saved result.\nPDFs are processed in memory. No network, upload or sandbox is provided.\nA disk/write failure can leave a partial NEW output; it is not deleted.\n"""\nimport argparse\nimport io\nimport sys\nimport stat\nfrom pathlib import Path\nfrom pypdf import PdfReader, PdfWriter\nfrom pypdf.errors import PyPdfError\n\n\ndef safe_input(value, directory=False):\n    path = Path(value).absolute()\n    if \'..\' in path.parts:\n        raise OSError(\'Parent-traversal paths are unsupported.\')\n    for part in [*reversed(path.parents), path]:\n        info = part.lstat()\n        if stat.S_ISLNK(info.st_mode) or getattr(info, \'st_file_attributes\', 0) & 0x400:\n            raise OSError(\'Links/reparse points are unsupported.\')\n    info = path.lstat()\n    if directory:\n        if not stat.S_ISDIR(info.st_mode):\n            raise NotADirectoryError(\'Expected an ordinary directory.\')\n    elif not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:\n        raise OSError(\'Expected an ordinary singly linked file.\')\n    return path\n\ndef safe_output(value):\n    path = Path(value).absolute()\n    if \'..\' in path.parts:\n        raise OSError(\'Parent-traversal paths are unsupported.\')\n    safe_input(path.parent, directory=True)\n    return Path(value)\n\n\ndef reader(path):\n    path = safe_input(path)\n    pdf = PdfReader(path)\n    if pdf.is_encrypted:\n        raise ValueError(\'Encrypted PDFs are not supported by this lesson.\')\n    return pdf\n\n\ndef save_new(writer, path):\n    safe_output(path)\n    # Check links themselves: Windows xb may follow a dangling symlink.\n    # This check plus exclusive creation is not a hostile-race guarantee.\n    try:\n        Path(path).lstat()\n    except FileNotFoundError:\n        pass\n    else:\n        raise FileExistsError(path)\n    # Finish serialization before creating a new destination.\n    data = io.BytesIO()\n    writer.write(data)\n    with open(path, \'xb\') as handle:\n        handle.write(data.getvalue())\n\n\ndef count(paths):\n    counts = [(path, len(reader(path).pages)) for path in paths]\n    for path, n in counts:\n        print(\'%s: %d page%s\' % (path, n, \'\' if n == 1 else \'s\'))\n    if len(counts) > 1:\n        print(\'Total: %d pages\' % sum(n for _, n in counts))\n\n\ndef merge(out, inputs):\n    writer = PdfWriter()\n    for path in inputs:\n        for page in reader(path).pages:\n            writer.add_page(page)\n    save_new(writer, out)\n    print(\'Wrote %s with %d pages.\' % (out, len(writer.pages)))\n\n\ndef split(source, out, page_range):\n    parts = page_range.split(\'-\')\n    if len(parts) > 2 or not all(p.isascii() and p.isdigit() for p in parts):\n        raise ValueError(\'Range must be a positive page number or FIRST-LAST.\')\n    first, last = int(parts[0]), int(parts[-1])\n    pdf = reader(source)\n    if not 1 <= first <= last <= len(pdf.pages):\n        raise ValueError(\'Range %s does not fit %d pages.\' % (page_range, len(pdf.pages)))\n    writer = PdfWriter()\n    for page in pdf.pages[first - 1:last]:\n        writer.add_page(page)\n    save_new(writer, out)\n    print(\'Wrote %s with source pages %d-%d.\' % (out, first, last))\n\n\ndef rotate(source, out, degrees, page_no):\n    pdf = reader(source)\n    if page_no is not None and not 1 <= page_no <= len(pdf.pages):\n        raise ValueError(\'Requested page does not exist.\')\n    writer = PdfWriter()\n    for i, page in enumerate(pdf.pages, 1):\n        if page_no is None or i == page_no:\n            page.rotate(degrees)\n        writer.add_page(page)\n    save_new(writer, out)\n    print(\'Wrote %s; rotated %s by %d degrees.\' % (out, \'all pages\' if page_no is None else \'page %d\' % page_no, degrees))\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(description=__doc__)\n    sub = parser.add_subparsers(dest=\'command\', required=True)\n    p = sub.add_parser(\'count\'); p.add_argument(\'inputs\', nargs=\'+\')\n    p = sub.add_parser(\'merge\'); p.add_argument(\'out\'); p.add_argument(\'inputs\', nargs=\'+\')\n    p = sub.add_parser(\'split\'); p.add_argument(\'source\'); p.add_argument(\'out\'); p.add_argument(\'page_range\')\n    p = sub.add_parser(\'rotate\'); p.add_argument(\'source\'); p.add_argument(\'out\'); p.add_argument(\'degrees\', type=int, choices=[90, 180, 270]); p.add_argument(\'--page\', type=int)\n    args = parser.parse_args(argv)\n    try:\n        if args.command == \'count\': count(args.inputs)\n        elif args.command == \'merge\': merge(args.out, args.inputs)\n        elif args.command == \'split\': split(args.source, args.out, args.page_range)\n        else: rotate(args.source, args.out, args.degrees, args.page)\n    except FileExistsError:\n        print(\'Stopped: destination already exists. Nothing was replaced.\', file=sys.stderr)\n        return 1\n    except (OSError, ValueError, PyPdfError) as error:\n        print(\'Stopped: %s\' % error, file=sys.stderr)\n        return 1\n    return 0\n\n\nif __name__ == \'__main__\':\n    sys.exit(main())\n', 'check38.py': '"""Limited fixture checks, not a validator for real PDFs or feature preservation."""\nimport hashlib\nimport json\nimport sys\nimport stat\nfrom pathlib import Path\nfrom pypdf import PdfReader\nfrom pypdf.errors import PyPdfError\n\n\ndef safe_input(value, directory=False):\n    path = Path(value).absolute()\n    if \'..\' in path.parts:\n        raise OSError(\'Parent-traversal paths are unsupported.\')\n    for part in [*reversed(path.parents), path]:\n        info = part.lstat()\n        if stat.S_ISLNK(info.st_mode) or getattr(info, \'st_file_attributes\', 0) & 0x400:\n            raise OSError(\'Links/reparse points are unsupported.\')\n    info = path.lstat()\n    if directory:\n        if not stat.S_ISDIR(info.st_mode):\n            raise NotADirectoryError(\'Expected an ordinary directory.\')\n    elif not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:\n        raise OSError(\'Expected an ordinary singly linked file.\')\n    return path\n\ndef safe_output(value):\n    path = Path(value).absolute()\n    if \'..\' in path.parts:\n        raise OSError(\'Parent-traversal paths are unsupported.\')\n    safe_input(path.parent, directory=True)\n    return Path(value)\n\n\ndef digest(path):\n    return hashlib.sha256(safe_input(path).read_bytes()).hexdigest()\n\n\ndef pages(path):\n    return [(p.extract_text().strip(), tuple(float(x) for x in p.mediabox), int(p.get(\'/Rotate\', 0)) % 360)\n            for p in PdfReader(safe_input(path)).pages]\n\n\ndef verify(root):\n    root = safe_input(root, directory=True)\n    sources = [root / (name + \'.pdf\') for name in [\'contract\', \'invoice\', \'notes\']]\n    before = json.loads(safe_input(root / \'sources.sha256.json\').read_text())\n    assert before == {p.name: digest(p) for p in sources}, \'Source bytes changed\'\n    original = sum((pages(p) for p in sources), [])\n    expected = [\'FICTIONAL CONTRACT - PAGE 1\', \'FICTIONAL CONTRACT - PAGE 2\',\n        \'FICTIONAL INVOICE - PAGE 1\', \'FICTIONAL INVOICE - PAGE 2\',\n        \'FICTIONAL INVOICE - PAGE 3\', \'FICTIONAL NOTES - PAGE 1\']\n    assert [x[0] for x in original] == expected, \'Unexpected fixture labels\'\n    assert pages(root / \'merged.pdf\') == original, \'Merged content/order/geometry/rotation differs\'\n    assert pages(root / \'first.pdf\') == original[:2], \'Split content/order differs\'\n    notes = pages(root / \'notes.pdf\')[0]\n    assert pages(root / \'rotated.pdf\') == [(notes[0], notes[1], (notes[2] + 90) % 360)], \'Rotation differs\'\n    print(\'PASS: all source SHA256 digests unchanged; six fixture labels and their order match.\')\n    print(\'PASS: merged page geometry/rotation match; split selects first two labels; notes rotation is 90 degrees.\')\n    print(\'These checks do not prove visual appearance or document-feature preservation. Inspect the PDFs.\')\n\n\ndef snapshot(root):\n    root = safe_input(root, directory=True)\n    manifest = safe_output(root / \'sources.sha256.json\')\n    try:\n        manifest.lstat()\n    except FileNotFoundError:\n        pass\n    else:\n        raise FileExistsError(manifest)\n    data = {name + \'.pdf\': digest(root / (name + \'.pdf\')) for name in [\'contract\', \'invoice\', \'notes\']}\n    with manifest.open(\'x\', encoding=\'ascii\') as handle:\n        json.dump(data, handle, sort_keys=True)\n    print(\'Saved source SHA256 digests in a new manifest; existing manifests are refused.\')\n\n\ndef main(argv):\n    if argv not in ([\'snapshot\'], [\'verify\']):\n        print(\'Usage: python check38.py snapshot|verify\', file=sys.stderr)\n        return 2\n    try:\n        root = Path(__file__).absolute().parent / \'sample\'\n        if argv == [\'snapshot\']:\n            snapshot(root)\n        else:\n            verify(root)\n    except (OSError, ValueError, AssertionError, PyPdfError) as error:\n        print(\'Stopped: \' + str(error), file=sys.stderr)\n        return 2\n    return 0\n\n\nif __name__ == \'__main__\':\n    sys.exit(main(sys.argv[1:]))\n', 'test_pdfkit.py': '"""Small fictional fixture tests. No real documents or all-feature guarantee."""\nfrom unittest import mock\nimport contextlib\nimport io\nimport json\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport tempfile\nimport unittest\nfrom pypdf import PdfReader, PdfWriter\nimport check38\nimport make_sample\nimport pdfkit\n\nTOOL = str(Path(pdfkit.__file__).resolve())\n\n\nclass PdfKitTests(unittest.TestCase):\n    def setUp(self):\n        self.temp = tempfile.TemporaryDirectory()\n        self.addCleanup(self.temp.cleanup)\n        self.root = Path(self.temp.name)\n        self.sample = self.root / \'sample\'\n        make_sample.setup(self.sample)\n        self.a, self.b = self.sample / \'contract.pdf\', self.sample / \'invoice.pdf\'\n        self.out = self.root / \'output.pdf\'\n\n    def run_tool(self, *args):\n        return subprocess.run([sys.executable, TOOL, *map(str, args)], capture_output=True, text=True)\n\n    def snapshot(self, p):\n        return p.read_bytes(), p.stat().st_mtime_ns\n\n    def operations(self, out):\n        return [(\'merge\', out, self.a, self.b), (\'split\', self.a, out, \'1-2\'), (\'rotate\', self.a, out, \'90\')]\n\n    def test_count_reports_each_file_and_total(self):\n        r = self.run_tool(\'count\', self.a, self.b)\n        self.assertEqual(r.returncode, 0); self.assertIn(\'Total: 5 pages\', r.stdout)\n\n    def test_merge_preserves_order_text_geometry_and_rotation(self):\n        self.assertEqual(self.run_tool(\'merge\', self.out, self.a, self.b).returncode, 0)\n        self.assertEqual(check38.pages(self.out), check38.pages(self.a) + check38.pages(self.b))\n\n    def test_split_selects_requested_labels(self):\n        self.assertEqual(self.run_tool(\'split\', self.b, self.out, \'2-3\').returncode, 0)\n        self.assertEqual(check38.pages(self.out), check38.pages(self.b)[1:3])\n\n    def test_split_single_page(self):\n        self.assertEqual(self.run_tool(\'split\', self.b, self.out, \'2\').returncode, 0)\n        self.assertEqual(check38.pages(self.out), check38.pages(self.b)[1:2])\n\n    def test_rotate_all_preserves_text_geometry_and_changes_rotation(self):\n        self.assertEqual(self.run_tool(\'rotate\', self.a, self.out, \'90\').returncode, 0)\n        self.assertEqual(check38.pages(self.out), [(t, b, (r + 90) % 360) for t, b, r in check38.pages(self.a)])\n\n    def test_rotate_only_selected_page(self):\n        self.assertEqual(self.run_tool(\'rotate\', self.b, self.out, \'180\', \'--page\', \'2\').returncode, 0)\n        expected = [(t, b, (r + (180 if i == 1 else 0)) % 360) for i, (t, b, r) in enumerate(check38.pages(self.b))]\n        self.assertEqual(check38.pages(self.out), expected)\n\n    def test_existing_output_preserves_bytes_and_mtime_for_each_operation(self):\n        self.out.write_bytes(b\'KEEP PRIVATE DATA\'); before = self.snapshot(self.out)\n        for args in self.operations(self.out):\n            with self.subTest(command=args[0]):\n                r = self.run_tool(*args); self.assertEqual(r.returncode, 1)\n                self.assertIn(\'already exists\', r.stderr); self.assertEqual(before, self.snapshot(self.out))\n\n    def test_existing_empty_output_is_refused(self):\n        self.out.touch(); before = self.snapshot(self.out)\n        for args in self.operations(self.out):\n            self.assertEqual(self.run_tool(*args).returncode, 1); self.assertEqual(before, self.snapshot(self.out))\n\n    def test_output_equal_to_input_preserves_bytes_and_mtime(self):\n        before = self.snapshot(self.a)\n        for args in self.operations(self.a):\n            self.assertEqual(self.run_tool(*args).returncode, 1); self.assertEqual(before, self.snapshot(self.a))\n\n    def test_relative_alias_of_input_is_refused(self):\n        alias = str(self.a.parent / \'.\' / self.a.name); before = self.snapshot(self.a)\n        self.assertEqual(self.run_tool(\'merge\', alias, self.a).returncode, 1)\n        self.assertEqual(before, self.snapshot(self.a))\n\n    def test_input_hardlink_output_is_refused(self):\n        os.link(self.a, self.out); before = self.snapshot(self.a)\n        for args in self.operations(self.out):\n            self.assertEqual(self.run_tool(*args).returncode, 1); self.assertEqual(before, self.snapshot(self.a))\n\n    def test_existing_directory_is_refused_without_touching_child(self):\n        self.out.mkdir(); child = self.out / \'private\'; child.write_bytes(b\'KEEP\'); before = self.snapshot(child)\n        for args in self.operations(self.out):\n            self.assertNotEqual(self.run_tool(*args).returncode, 0); self.assertEqual(before, self.snapshot(child))\n\n    def test_symlink_and_dangling_symlink_output_are_refused(self):\n        try: self.out.symlink_to(self.a)\n        except OSError: self.skipTest(\'Symlink creation is not available\')\n        before = self.snapshot(self.a)\n        for args in self.operations(self.out):\n            self.assertEqual(self.run_tool(*args).returncode, 1); self.assertEqual(before, self.snapshot(self.a))\n        self.out.unlink(); target = self.root / \'absent.pdf\'; self.out.symlink_to(target)\n        for args in self.operations(self.out):\n            self.assertEqual(self.run_tool(*args).returncode, 1); self.assertFalse(target.exists()); self.assertTrue(self.out.is_symlink())\n\n    def test_input_bytes_and_mtime_unchanged_after_success(self):\n        before = {p: self.snapshot(p) for p in [self.a, self.b]}\n        for i, args in enumerate(self.operations(self.out)):\n            args = (args[0], *[self.root / (\'out%d.pdf\' % i) if x == self.out else x for x in args[1:]])\n            self.assertEqual(self.run_tool(*args).returncode, 0)\n        self.assertEqual(before, {p: self.snapshot(p) for p in before})\n\n    def test_bad_ranges_create_no_output(self):\n        for value in [\'0\', \'2-1\', \'1-99\', \'x\', \'1-\', \'1-2-3\', \'-1\']:\n            with self.subTest(value=value):\n                self.assertNotEqual(self.run_tool(\'split\', self.a, self.out, value).returncode, 0)\n                self.assertFalse(self.out.exists())\n\n    def test_bad_rotation_or_page_creates_no_output(self):\n        for args in [(\'45\',), (\'x\',), (\'90\', \'--page\', \'0\'), (\'90\', \'--page\', \'99\'), (\'90\', \'--page\'), (\'90\', \'--unknown\')]:\n            self.assertNotEqual(self.run_tool(\'rotate\', self.a, self.out, *args).returncode, 0); self.assertFalse(self.out.exists())\n\n    def test_missing_or_malformed_input_creates_no_output(self):\n        bad = self.root / \'bad.pdf\'; bad.write_bytes(b\'not a PDF\')\n        for p in [bad, self.root / \'missing.pdf\']:\n            for args in [(\'merge\', self.out, self.a, p), (\'split\', p, self.out, \'1\'), (\'rotate\', p, self.out, \'90\')]:\n                self.assertNotEqual(self.run_tool(*args).returncode, 0); self.assertFalse(self.out.exists())\n\n    def test_encrypted_input_is_refused(self):\n        writer = PdfWriter(); writer.add_blank_page(width=100, height=100); writer.encrypt(\'fictional-test-password\')\n        p = self.root / \'encrypted.pdf\'\n        with p.open(\'xb\') as h: writer.write(h)\n        self.assertEqual(self.run_tool(\'merge\', self.out, p).returncode, 1); self.assertFalse(self.out.exists())\n\n    def test_setup_refuses_existing_folder_and_preserves_nested_data(self):\n        p = self.sample / \'nested\'; p.mkdir(); child = p / \'keep\'; child.write_bytes(b\'KEEP\'); before = self.snapshot(child)\n        with self.assertRaises(FileExistsError): make_sample.setup(self.sample)\n        self.assertEqual(before, self.snapshot(child))\n\n    def test_setup_refuses_existing_file_and_preserves_mtime(self):\n        p = self.root / \'old\'; p.write_bytes(b\'KEEP\'); before = self.snapshot(p)\n        with self.assertRaises(FileExistsError): make_sample.setup(p)\n        self.assertEqual(before, self.snapshot(p))\n\n    def test_setup_repeat_preserves_all_generated_files(self):\n        before = {p: self.snapshot(p) for p in self.sample.iterdir()}\n        with self.assertRaises(FileExistsError): make_sample.setup(self.sample)\n        self.assertEqual(before, {p: self.snapshot(p) for p in before})\n\n    def test_fixture_checker_detects_reordered_merged_pages(self):\n        sources = [self.sample / (n + \'.pdf\') for n in [\'contract\', \'invoice\', \'notes\']]\n        (self.sample / \'sources.sha256.json\').write_text(json.dumps({p.name: check38.digest(p) for p in sources}))\n        with contextlib.redirect_stdout(io.StringIO()): pdfkit.merge(self.sample / \'merged.pdf\', list(reversed(sources)))\n        with contextlib.redirect_stdout(io.StringIO()): pdfkit.split(self.a, self.sample / \'first.pdf\', \'1-2\')\n        with contextlib.redirect_stdout(io.StringIO()): pdfkit.rotate(sources[-1], self.sample / \'rotated.pdf\', 90, None)\n        with self.assertRaisesRegex(AssertionError, \'Merged\'): check38.verify(self.sample)\n\n    def test_named_pipe_input_is_rejected_without_blocking(self):\n        if not hasattr(os, \'mkfifo\'): self.skipTest(\'Named pipes unavailable\')\n        p = self.root / \'pipe\'; os.mkfifo(p)\n        r = self.run_tool(\'merge\', self.out, p)\n        self.assertEqual(r.returncode, 1); self.assertFalse(self.out.exists())\n\n    def test_serialization_failure_creates_no_destination(self):\n        class BrokenWriter:\n            def write(self, handle):\n                handle.write(b\'partial\'); raise ValueError(\'fictional serialization failure\')\n        with self.assertRaises(ValueError): pdfkit.save_new(BrokenWriter(), self.out)\n        self.assertFalse(self.out.exists())\n\n    def test_fixture_success_then_source_digest_tamper_is_detected(self):\n        sources = [self.sample / (n + \'.pdf\') for n in [\'contract\', \'invoice\', \'notes\']]\n        (self.sample / \'sources.sha256.json\').write_text(json.dumps({p.name: check38.digest(p) for p in sources}))\n        with contextlib.redirect_stdout(io.StringIO()):\n            pdfkit.merge(self.sample / \'merged.pdf\', sources)\n            pdfkit.split(self.a, self.sample / \'first.pdf\', \'1-2\')\n            pdfkit.rotate(sources[-1], self.sample / \'rotated.pdf\', 90, None)\n            check38.verify(self.sample)\n        with self.a.open(\'ab\') as handle: handle.write(b\'tampered\')\n        with self.assertRaisesRegex(AssertionError, \'Source bytes changed\'): check38.verify(self.sample)\n\n    def test_setup_cli_refuses_repeat_without_changing_sample(self):\n        script = self.root / \'make_sample.py\'; script.write_text(Path(make_sample.__file__).read_text())\n        before = {p: self.snapshot(p) for p in self.sample.iterdir()}\n        r = subprocess.run([sys.executable, str(script)], capture_output=True, text=True)\n        self.assertEqual(r.returncode, 1); self.assertIn(\'sample already exists\', r.stderr)\n        self.assertEqual(before, {p: self.snapshot(p) for p in before})\n\n    def test_manifest_existing_file_preserved(self):\n        p = self.sample / \'sources.sha256.json\'; p.write_bytes(b\'KEEP\'); before = self.snapshot(p)\n        with self.assertRaises(FileExistsError): check38.snapshot(self.sample)\n        self.assertEqual(before, self.snapshot(p))\n\n    def test_manifest_dangling_link_refused(self):\n        p = self.sample / \'sources.sha256.json\'; target = self.root / \'absent.json\'\n        try: p.symlink_to(target)\n        except OSError: self.skipTest(\'Symlink creation is not available\')\n        with self.assertRaises(FileExistsError): check38.snapshot(self.sample)\n        self.assertFalse(target.exists()); self.assertTrue(p.is_symlink())\n\n    def test_setup_existing_and_dangling_directory_links_refused(self):\n        link = self.root / \'linked\'; absent = self.root / \'absent-dir\'\n        try: link.symlink_to(self.sample, target_is_directory=True)\n        except OSError: self.skipTest(\'Symlink creation is not available\')\n        before = {p: self.snapshot(p) for p in self.sample.iterdir()}\n        with self.assertRaises(FileExistsError): make_sample.setup(link)\n        self.assertEqual(before, {p: self.snapshot(p) for p in before})\n        link.unlink(); link.symlink_to(absent, target_is_directory=True)\n        with self.assertRaises(FileExistsError): make_sample.setup(link)\n        self.assertFalse(absent.exists()); self.assertTrue(link.is_symlink())\n\n    def test_help_and_unknown_command(self):\n        self.assertEqual(self.run_tool(\'--help\').returncode, 0)\n        self.assertNotEqual(self.run_tool(\'wrong\').returncode, 0)\n        self.assertNotEqual(self.run_tool().returncode, 0)\n\n\nclass PathSafety(unittest.TestCase):\n    def setUp(self):\n        self.tmp=tempfile.TemporaryDirectory();self.addCleanup(self.tmp.cleanup)\n        self.base=Path(self.tmp.name);self.root=self.base/\'tree\';self.root.mkdir()\n        self.file=self.root/\'zero\';self.file.write_bytes(b\'\')\n    def link(self,path,target,directory=False):\n        try:path.symlink_to(target,target_is_directory=directory)\n        except OSError:self.skipTest(\'Symlinks unavailable\')\n    def code(self,path):\n        with contextlib.redirect_stderr(io.StringIO()):\n            return pdfkit.main([\'count\',str(path)])\n    def test_root_alias_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.root,True);self.assertEqual(self.code(p),1)\n    def test_ancestor_alias_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.base,True);self.assertEqual(self.code(p/\'tree\'),1)\n    def test_file_alias_refuses(self):\n        p=self.base/\'linked\';self.link(p,self.file);self.assertEqual(self.code(p),1)\n    def test_file_hardlink_refuses(self):\n        p=self.base/\'hard\';os.link(self.file,p);self.assertEqual(self.code(p),1)\n    def test_file_pipe_refuses(self):\n        if not hasattr(os,\'mkfifo\'):self.skipTest(\'Unix pipe unavailable\')\n        p=self.base/\'pipe\';os.mkfifo(p);self.assertEqual(self.code(p),1)\n    def test_file_self_loop_refuses(self):\n        p=self.base/\'loop\';self.link(p,p);self.assertEqual(self.code(p),1)\n    def test_file_dangling_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.base/\'missing\');self.assertEqual(self.code(p),1)\n    def test_file_traversal_refuses(self):self.assertEqual(self.code(self.root/\'..\'/\'tree\'/\'zero\'),1)\n    def test_file_ancestor_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.root,True);self.assertEqual(self.code(p/\'zero\'),1)\n    def test_metadata_error_refuses(self):\n        with mock.patch.object(Path,\'lstat\',side_effect=OSError(\'forced\')):self.assertEqual(self.code(self.file),1)\n    def test_reparse_attribute_refuses(self):\n        real=Path.lstat\n        def fake(p,*a,**kw):\n            value=real(p,*a,**kw)\n            if p==self.file:return type(\'Reparse\',(),{\'st_mode\':value.st_mode,\'st_file_attributes\':0x400})()\n            return value\n        with mock.patch.object(Path,\'lstat\',fake):self.assertEqual(self.code(self.file),1)\n\n\n    def test_read_error_stops(self):\n        with mock.patch.object(Path,\'open\',side_effect=OSError(\'forced\')):\n            self.assertEqual(self.code(self.file),1)\n    def test_setup_alias_parent_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.root,True)\n        with self.assertRaises(OSError):make_sample.setup(p/\'new\')\n        self.assertFalse((self.root/\'new\').exists())\n    def test_setup_traversal_refuses(self):\n        with self.assertRaises(OSError):make_sample.setup(self.root/\'..\'/\'new\')\n    def test_output_linked_parent_refuses(self):\n        p=self.base/\'alias\';self.link(p,self.root,True)\n        with self.assertRaises(OSError):pdfkit.safe_output(p/\'new\')\n        self.assertFalse((self.root/\'new\').exists())\n    def test_output_traversal_refuses(self):\n        with self.assertRaises(OSError):pdfkit.safe_output(self.root/\'..\'/\'new\')\n    def test_output_metadata_error_refuses(self):\n        with mock.patch.object(Path,\'lstat\',side_effect=OSError(\'forced\')):\n            with self.assertRaises(OSError):pdfkit.safe_output(self.root/\'new\')\n\n\n    def test_fixture_digest_alias_refuses(self):\n        p=self.base/\'linked\';self.link(p,self.file)\n        with self.assertRaises(OSError):check38.digest(p)\n    def test_fixture_pages_alias_refuses(self):\n        p=self.base/\'linked\';self.link(p,self.file)\n        with mock.patch.object(check38,\'PdfReader\') as reader:\n            with self.assertRaises(OSError):check38.pages(p)\n            reader.assert_not_called()\n    def test_pdf_reader_error_reports_failure(self):\n        with mock.patch.object(pdfkit,\'PdfReader\',side_effect=OSError(\'forced\')),contextlib.redirect_stderr(io.StringIO()):\n            self.assertEqual(pdfkit.main([\'count\',str(self.file)]),1)\n    def test_fixture_cli_read_error_nonzero(self):\n        with mock.patch.object(Path,\'lstat\',side_effect=OSError(\'forced\')),contextlib.redirect_stderr(io.StringIO()):\n            self.assertEqual(check38.main([\'verify\']),2)\n\n\nif __name__ == \'__main__\':\n    unittest.main()\n'}
commands=[('python -c "import sys, pypdf; print(sys.version.split()[0]); print(pypdf.__version__)"', 0), ('python make_sample.py', 0), ('python make_sample.py', 1), ('python check38.py snapshot', 0), ('python pdfkit.py count sample/contract.pdf sample/invoice.pdf sample/notes.pdf', 0), ('python pdfkit.py merge sample/merged.pdf sample/contract.pdf sample/invoice.pdf sample/notes.pdf', 0), ('python pdfkit.py split sample/merged.pdf sample/first.pdf 1-2', 0), ('python pdfkit.py rotate sample/notes.pdf sample/rotated.pdf 90', 0), ('python check38.py verify', 0), ('python pdfkit.py merge sample/merged.pdf sample/contract.pdf sample/invoice.pdf sample/notes.pdf', 1), ('python check38.py verify', 0), ('python -m unittest -v', 0)]
with tempfile.TemporaryDirectory(prefix='lesson38-record-') as d:
 root=pathlib.Path(d)
 for name,text in files.items():(root/name).write_text(text,encoding='utf-8')
 for command,expected in commands:
  print('\n### CMD: '+command,flush=True)
  args=shlex.split(command)
  if args[0]=='python':args[0]=sys.executable
  before=None
  if 'merge sample/merged.pdf' in command and (root/'sample'/'merged.pdf').exists():
   p=root/'sample'/'merged.pdf';before=(p.read_bytes(),p.stat().st_mtime_ns)
  result=subprocess.run(args,cwd=root,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace')
  print(result.stdout,end='',flush=True);print('### EXIT: '+str(result.returncode),flush=True)
  if result.returncode!=expected:raise SystemExit('Unexpected exit')
  if before is not None:assert before==(p.read_bytes(),p.stat().st_mtime_ns), 'Refused output changed'
